    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2M14 15h2"/>',
    image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1"/><path d="m21 15-5-5L5 21"/>',battery:'<rect x="2" y="6" width="18" height="12" rx="2"/><path d="M23 10v4M5 9h11v6H5Z"/>',
    signal:'<path d="M4 20v-4M9 20v-8M14 20V8M19 20V4"/>',bluetooth:'<path d="m7 7 10 10-5 4V3l5 4L7 17"/>',flash:'<path d="m13 2-9 12h7l-1 8 10-12h-7l1-8Z"/>',
